/* ========================================
   GLOBAL STYLES & FONTS
======================================== */
@import url("./fonts.css");

* {
	margin: 0;
	padding: 0;
	box-sizing: border-box;
}

body {
	padding-top: 0;
	font-family: "Tronica Mono", monospace;
	background: black !important;
	color: white;
	transition: overflow 0.3s ease;
	font-smooth: never;
	-webkit-font-smoothing: none;
	-moz-osx-font-smoothing: grayscale;
}
img,
canvas,
svg {
	image-rendering: pixelated;
	image-rendering: crisp-edges;
}

a {
	text-decoration: none !important;
	color: white !important;
}

.container {
	max-width: 1300px;
	margin: 0 auto;
	padding: 0 1rem;
}

.section-title {
	font-family: "PP Mondwest", serif;
	font-size: clamp(2rem, 5vw, 4rem);
	text-align: left;
	margin-bottom: 2rem;
	position: relative;
	color: white;
}

/* ========================================
   NAVBAR
======================================== */
nav {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	z-index: 1001;
	display: flex;
	align-items: center;
	justify-content: space-between;
	padding: 1.2rem 2.5rem;
	font-family: "PP Mondwest", serif;
	background: transparent;
	transition: background 0.4s ease, padding 0.4s ease;
}

nav.scrolled {
	background: rgba(0, 0, 0, 0.6);
	backdrop-filter: blur(20px) saturate(180%);
	-webkit-backdrop-filter: blur(20px) saturate(180%);
	border-bottom: 1px solid rgba(255, 255, 255, 0.07);
	padding: 0.9rem 2.5rem;
}

/* Brand */
.brand {
	font-size: 1rem;
	letter-spacing: 0.18em;
	color: white;
	text-decoration: none;
	flex-shrink: 0;
	z-index: 1004;
}

/* ── Desktop nav links ── */
.nav-links {
	display: flex;
	gap: 2.5rem;
	list-style: none;
	align-items: center;
	position: absolute;
	left: 50%;
	transform: translateX(-50%);
}

.nav-links li a {
	font-size: 0.75rem;
	letter-spacing: 0.14em;
	color: rgba(255, 255, 255, 0.7);
	text-decoration: none;
	position: relative;
	padding-bottom: 3px;
	transition: color 0.3s ease;
}

.nav-links li a::after {
	content: "";
	position: absolute;
	bottom: 0;
	left: 0;
	width: 0;
	height: 1px;
	background: white;
	transition: width 0.35s cubic-bezier(0.76, 0, 0.24, 1);
}

.nav-links li a:hover { color: white; }
.nav-links li a:hover::after { width: 100%; }

/* Available dot */
.nav-avail {
	display: flex;
	align-items: center;
	gap: 0.5rem;
	font-size: 0.7rem;
	letter-spacing: 0.1em;
	color: rgba(255, 255, 255, 0.55);
	flex-shrink: 0;
}

.avail-dot {
	width: 7px;
	height: 7px;
	border-radius: 50%;
	background: #4ade80;
	display: block;
	animation: dotPulse 2s ease infinite;
}

@keyframes dotPulse {
	0%, 100% { opacity: 1;   transform: scale(1);   }
	50%       { opacity: 0.4; transform: scale(0.65); }
}

/* ── Hamburger — hidden on desktop ── */
.hamburger {
	display: none;
	flex-direction: column;
	justify-content: center;
	gap: 5px;
	width: 36px;
	height: 36px;
	padding: 0;
	background: none;
	border: none;
	cursor: pointer;
	z-index: 1004;
	flex-shrink: 0;
}

.hamburger span {
	display: block;
	width: 22px;
	height: 1.5px;
	background: white;
	border-radius: 2px;
	transition: transform 0.42s cubic-bezier(0.76, 0, 0.24, 1),
				opacity  0.42s ease;
	transform-origin: center;
}

.hamburger.active span:nth-child(1) { transform: translateY(6.5px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; transform: scaleX(0); }
.hamburger.active span:nth-child(3) { transform: translateY(-6.5px) rotate(-45deg); }

/* ========================================
   NAVBAR — MOBILE
======================================== */
@media (max-width: 768px) {
	nav {
		padding: 1rem 1.4rem;
		/* always slightly dark on mobile so brand is always readable */
		background: rgba(0, 0, 0, 0.45);
		backdrop-filter: blur(16px);
		-webkit-backdrop-filter: blur(16px);
	}

	nav.scrolled {
		padding: 0.8rem 1.4rem;
		background: rgba(0, 0, 0, 0.7);
	}

	.nav-avail { display: none; }
	.hamburger  { display: flex; }

	/* ── Full-screen overlay menu ──
	   backdrop-filter + clip-path on the SAME element cancel each other.
	   Use opacity/visibility instead — backdrop-filter works fine with those. */
	.nav-links {
		position: fixed;
		inset: 0;
		width: 100%;
		height: 100dvh;

		/* reset desktop absolute centering */
		left: 0;
		transform: none;

		flex-direction: column;
		justify-content: center;
		align-items: center;
		gap: 0;

		/* Frosted glass */
		background: rgba(8, 8, 8, 0.75);
		backdrop-filter: blur(28px) saturate(180%);
		-webkit-backdrop-filter: blur(28px) saturate(180%);

		/* hidden via opacity — does NOT break backdrop-filter */
		opacity: 0;
		visibility: hidden;
		pointer-events: none;
		transition: opacity 0.4s ease, visibility 0.4s ease;
		z-index: 1002;
	}

	.nav-links.open {
		opacity: 1;
		visibility: visible;
		pointer-events: auto;
	}

	/* Large tap-friendly links */
	.nav-links li {
		width: 100%;
		text-align: center;
		opacity: 0;
		transform: translateY(16px);
		transition: opacity 0.4s ease, transform 0.4s ease;
	}

	.nav-links.open li             { opacity: 1; transform: translateY(0); }
	.nav-links.open li:nth-child(1){ transition-delay: 0.18s; }
	.nav-links.open li:nth-child(2){ transition-delay: 0.24s; }
	.nav-links.open li:nth-child(3){ transition-delay: 0.30s; }
	.nav-links.open li:nth-child(4){ transition-delay: 0.36s; }
	.nav-links.open li:nth-child(5){ transition-delay: 0.42s; }

	.nav-links li a {
		display: block;
		padding: 1.1rem 2rem;
		font-size: 1.7rem;
		letter-spacing: 0.06em;
		color: rgba(255, 255, 255, 0.9);
	}

	.nav-links li a::after { display: none; }

	body.menu-open { overflow: hidden; }
}

/* Overlay backdrop */
.overlay {
	position: fixed;
	inset: 0;
	z-index: 1000;
	opacity: 0;
	visibility: hidden;
	transition: opacity 0.4s ease, visibility 0.4s ease;
}

.overlay.active {
	opacity: 1;
	visibility: visible;
}

/* ========================================
   HERO SECTION - BASE
======================================== */
.hero-section {
	position: relative;
	min-height: 100svh;
	width: 100%;
	overflow: hidden;
	display: grid;
	place-items: center;
	isolation: isolate;
}

/* Wrapper */
.cta-wrapper {
	display: flex;
	gap: 1em;
	text-align: center;
	align-items: center;
	justify-content: center;
	flex-wrap: wrap;
}

/* Base button style */
.btn-cta {
	background-color: #0c0c0c;
	border: none;
	border-radius: 50em;
	padding: 0.5em 1.5em;
	font-size: 1.2em;
	font-family: "PP Mondwest", serif;
	color: white;
	cursor: pointer;
	display: flex;
	align-items: center;
	justify-content: center;
	height: 3em;
	line-height: 1;
	position: relative;
	overflow: hidden;
	transition: all 0.4s cubic-bezier(0.23, 1, 0.32, 1);
	box-shadow: 0 0 0 0 rgba(255, 255, 255, 0);
}
/*  image */
.icon-img {
	width: 2.4em; /* Scales with text size */
	height: 2.4em;
	object-fit: contain;
	display: block;
}

/* Glowing hover effect */
.btn-cta:hover {
	background-color: #1a1a1a;
	box-shadow:
		0 0 20px rgba(255, 255, 255, 0.3),
		0 0 40px rgba(255, 255, 255, 0.2),
		0 0 60px rgba(255, 255, 255, 0.1),
		inset 0 0 20px rgba(255, 255, 255, 0.1);
	transform: translateY(-2px);
}

/* Animated glow ring */
.btn-cta::before {
	content: "";
	position: absolute;
	inset: -100px;
	border-radius: 50em;
	background: linear-gradient(
		45deg,
		transparent,
		rgba(82, 82, 82, 0.5),
		transparent
	);
	opacity: 0;
	transition: opacity 0.4s ease;
	animation: rotate 3s linear infinite;
	animation-play-state: paused;
}

.btn-cta:hover::before {
	opacity: 1;
	animation-play-state: running;
}

/* Inner glow pulse */
.btn-cta::after {
	content: "";
	position: absolute;
	inset: 0;
	border-radius: 50em;
	background: radial-gradient(
		circle at center,
		rgba(255, 255, 255, 0.2) 0%,
		transparent 70%
	);
	opacity: 0;
	transition: opacity 0.4s ease;
}

.btn-cta:hover::after {
	opacity: 1;
	animation: pulse 2s ease-in-out infinite;
}

/* Rotation animation for the border glow */
@keyframes rotate {
	0% {
		transform: rotate(0deg);
	}
	100% {
		transform: rotate(360deg);
	}
}

/* Pulse animation for inner glow */
@keyframes pulse {
	0%,
	100% {
		transform: scale(1);
		opacity: 0.5;
	}
	50% {
		transform: scale(1.05);
		opacity: 1;
	}
}

/* Icon button: make it a perfect circle */
.icon-btn {
	width: 3em;
	padding: 0;
}

/* SVG inside button - make sure it's above pseudo-elements */
.btn-cta svg,
.icon-svg {
	position: relative;
	z-index: 1;
	transition: all 0.4s ease;
}

.btn-cta:hover svg,
.btn-cta:hover .icon-svg {
	filter: drop-shadow(0 0 8px rgba(255, 255, 255, 0.8));
	transform: scale(1.05);
}

/* SVG styling */
.icon-svg {
	width: 1.5em;
	height: auto;
	fill: white;
	display: block;
}

.btn-cta svg {
	width: 2em;
	height: 2em;
	display: block;
}

/* Button container */
.cta-buttons {
	display: inline-flex;
	justify-content: center;
	align-items: center;
	gap: 1em;
}

/* Active/pressed state */
.btn-cta:active {
	transform: translateY(0);
	box-shadow:
		0 0 10px rgba(255, 255, 255, 0.2),
		inset 0 0 20px rgba(255, 255, 255, 0.15);
}

/* Ensure text is above pseudo-elements */
.btn-cta {
	z-index: 1;
}

.btn-cta > * {
	position: relative;
	z-index: 2;
}

#bg-video {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 100%;
	object-fit: cover;
	z-index: -1;
	pointer-events: none;
}
.name {
