/* ========================================
  SECTIONS - BASE
======================================== */

.section-container {
	padding: 3rem 0;
}

/* ========================================
   PROJECTS SECTION - BASE
======================================== */
/* Projects Grid Container */
.projects-container {
	max-width: 1400px;
	margin: 0 auto;
	display: grid;
	grid-template-columns: repeat(2, 1fr); /* Exactly 2 columns */
	gap: 2rem;
	align-items: stretch; /* Makes all cards same height */
	padding: 2rem 0;
}

/* Card Container */
.project-card {
	width: 100%;
	background: linear-gradient(180deg, #1a1a1a 0%, #0a0a0a 100%);
	border-radius: 16px;
	overflow: hidden;
	border: 1px solid #2a2a2a;
	box-shadow:
		0 10px 40px rgba(0, 0, 0, 0.5),
		0 0 0 1px rgba(255, 255, 255, 0.05);
	flex-direction: column; /* Add this */
	height: auto; /* Ensures cards fill grid cell height */
	display: flex;
	flex-direction: column;
	transition:
		transform 0.3s ease,
		box-shadow 0.3s ease;
}

.project-card:hover {
	transform: translateY(-8px);
	box-shadow:
		0 20px 60px rgba(0, 0, 0, 0.7),
		0 0 0 1px rgba(255, 255, 255, 0.1);
}

.card-image {
	width: 100%;
	aspect-ratio: 16 / 9; /* Keeps image container at 16:9 on all devices */
	overflow: hidden;
	position: relative;
	flex-shrink: 0;
	border-bottom: 2px solid #ffffff10; /* Optional for subtle border */
}

.card-image img {
	width: 100%;
	height: 100%;
	object-fit: cover;
	transition: transform 0.5s ease;
}

.project-card:hover .card-image img {
	transform: scale(1.05);
}

/* Content Section */
.card-content {
	padding: 1.5rem;
	display: flex; /* Add this */
	flex-direction: column; /* Add this */
	min-height: 0; /* Fixes potential overflow issues */
	flex: 1; /* Add this - makes content fill available space */
	justify-content: space-between;
}

/* Header with Title and Tech Stack */
.card-header {
	display: flex;
	justify-content: space-between;
	align-items: flex-start;
	margin-bottom: 1rem;
	padding-bottom: 1rem;
	border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.card-title {
	font-size: 1.1rem;
	font-weight: 700;
	letter-spacing: 0.05em;
	color: #fff;
	text-transform: uppercase;
	line-height: 1.3;
	flex: 1;
	margin-right: 1rem;
}

/* Tech Stack Icons */
.tech-stack {
	display: flex;
	gap: 0.5rem;
	align-items: center;
	flex-shrink: 0;
}

.tech-icon {
	width: 32px;
	height: 32px;
	display: flex;
	align-items: center;
	justify-content: center;
	background: rgba(255, 255, 255, 0.05);
	border: 1px solid rgba(255, 255, 255, 0.1);
	border-radius: 6px;
	font-size: 0.7rem;
	font-weight: 700;
	color: #fff;
	transition: all 0.3s ease;
}

.tech-icon svg {
	width: 18px;
	height: 18px;
}

.tech-text {
	font-size: 0.65rem;
}

.tech-icon:hover {
	background: rgba(0, 212, 255, 0.1);
	border-color: #ffffff;
	transform: translateY(-2px);
}

.card-description {
	font-size: clamp(0.75rem, 1vw, 0.85rem);
	line-height: 1.6;
	color: rgba(255, 255, 255, 0.7);
	margin-bottom: 1.25rem;
	flex-grow: 0; /* Don't let description push button down unnecessarily */
}

/* Impact Section */
.card-impact {
	background: rgba(255, 255, 255, 0.05);
	border-left: 3px solid #ffffff;
	padding: 1rem;
	margin-bottom: 1.5rem;
	border-radius: 4px;
	flex-grow: 0; /* Don't let impact section grow */
}

.impact-title {
	font-size: 1rem;
	font-weight: 700;
	color: #ffffff;
	margin-bottom: 0.5rem;
	text-transform: uppercase;
	letter-spacing: 0.05em;
}

.impact-text {
	font-size: clamp(0.75rem, 1vw, 0.85rem);
	line-height: 1.6;
	color: rgba(255, 255, 255, 0.7);
}

/* Case Study Button */
.case-study-btn {
	width: 100%;
	padding: 0.875rem 1.5rem;
	background: transparent;
	border: 2px solid #ffffff;
	border-radius: 8px;
	color: #ffffff;
	font-family: "Tronica Mono", monospace;
	font-size: 0.875rem;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: 0.05em;
	cursor: pointer;
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 0.5rem;
	transition: all 0.3s ease;
	position: relative;
	overflow: hidden;
	margin-top: auto; /* This pushes the button to the bottom */
	flex-shrink: 0; /* Prevents button from shrinking */
}

.case-study-btn::before {
	content: "";
	position: absolute;
	top: 0;
	left: -100%;
	width: 100%;
	height: 100%;
	background: linear-gradient(
		90deg,
		transparent,
		rgba(255, 255, 255, 0.2),
		transparent
	);
	transition: left 0.5s ease;
}

.case-study-btn:hover::before {
	left: 100%;
}

.case-study-btn:hover {
	background: white;
	color: #000;
	box-shadow: 0 0 20px rgba(255, 255, 255, 0.5);
	transform: translateY(-2px);
}

.arrow-icon {
	width: 20px;
	height: 20px;
	transition: transform 0.3s ease;
}

.case-study-btn:hover .arrow-icon {
	transform: translateX(4px);
}

/* Responsive Design */
@media (max-width: 1200px) {
	.projects-container {
		grid-template-columns: 1fr; /* Exactly 1 column on mobile */
	}
}

@media (max-width: 768px) {
	.projects-container {
		grid-template-columns: 1fr;
		gap: 1.5rem;
	}

	.card-title {
		font-size: 0.95rem;
	}

	.card-image {
		aspect-ratio: unset;
	}

	.tech-icon {
		width: 28px;
		height: 28px;
	}

	.tech-icon svg {
		width: 16px;
		height: 16px;
	}
}

@media (max-width: 480px) {
	.card-header {
		flex-direction: column;
		gap: 1rem;
	}

	.card-title {
		margin-right: 0;
	}

	.tech-stack {
		align-self: flex-start;
	}
}

